+        browser.addEventListener("load", resolve, { once: true, capture: true })
+      );
+    }
+
+    this.#browser = browser;
+    this.hasConnected = true;
+
+    if (this.#data) {
+      this.setDescription(...this.#data);
+      this.#data = null;
+    }
   }

